// Todas las webs en una sola ejecución (modo "Run Once for All Items") a
// propósito: las claves de los agentes salen descifradas de Vault y no deben
// viajar como items entre nodos, porque n8n guarda los items de cada nodo en
// el historial de ejecuciones. Aquí solo sale un resumen sin claves.
//
// Si un agente no responde, no se toca su inventario ni agent_last_seen_at:
// el panel lo mostrará como caducado a las 48 h (§6 del SPEC), nunca como
// "al día" con datos viejos.
const supabaseHeaders = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json',
};

const targets = await this.helpers.httpRequest({
  method: 'POST',
  url: `${$env.SUPABASE_URL}/rest/v1/rpc/agent_targets`,
  headers: supabaseHeaders,
  body: {},
  json: true,
});

const results = [];

for (const target of targets) {
  const endpoint = `${target.url.replace(/\/+$/, '')}/wp-json/panel/v1/status`;

  let response;
  try {
    response = await this.helpers.httpRequest({
      method: 'GET',
      url: endpoint,
      headers: { 'X-Panel-Key': target.agent_key, Accept: 'application/json' },
      json: true,
      timeout: 20000,
      ignoreHttpStatusErrors: true,
      returnFullResponse: true,
    });
  } catch (err) {
    results.push({ site_id: target.site_id, ok: false, error: err.message });
    continue;
  }

  const body = response.body;
  if (response.statusCode !== 200 || !body || typeof body !== 'object' || !body.wp_version) {
    results.push({ site_id: target.site_id, ok: false, error: `HTTP ${response.statusCode}` });
    continue;
  }

  const collectedAt = new Date().toISOString();

  // Lista explícita de columnas: lo que no venga del agente se guarda null,
  // nunca un valor por defecto que parezca un dato.
  const pick = (key) => (body[key] === undefined ? null : body[key]);

  await this.helpers.httpRequest({
    method: 'POST',
    url: `${$env.SUPABASE_URL}/rest/v1/site_inventory`,
    qs: { on_conflict: 'site_id' },
    headers: { ...supabaseHeaders, Prefer: 'resolution=merge-duplicates,return=minimal' },
    body: {
      site_id: target.site_id,
      collected_at: collectedAt,
      wp_version: pick('wp_version'),
      php_version: pick('php_version'),
      core_update_available: pick('core_update_available'),
      plugins: Array.isArray(body.plugins) ? body.plugins : [],
      themes: Array.isArray(body.themes) ? body.themes : [],
      updates_pending: pick('updates_pending'),
      updates_checked_at: pick('updates_checked_at'),
      admin_count: pick('admin_count'),
      debug_enabled: pick('debug_enabled'),
      search_engines_discouraged: pick('search_engines_discouraged'),
      db_size_mb: pick('db_size_mb'),
      db_revisions: pick('db_revisions'),
      db_expired_transients: pick('db_expired_transients'),
      db_autoload_kb: pick('db_autoload_kb'),
      last_backup_at: pick('last_backup_at'),
      backup_source: pick('backup_source'),
    },
    json: true,
  });

  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${$env.SUPABASE_URL}/rest/v1/sites`,
    qs: { id: `eq.${target.site_id}` },
    headers: { ...supabaseHeaders, Prefer: 'return=minimal' },
    body: { agent_last_seen_at: collectedAt },
    json: true,
  });

  results.push({
    site_id: target.site_id,
    ok: true,
    wp_version: body.wp_version,
    updates_pending: pick('updates_pending'),
  });
}

return results.map((json) => ({ json }));
